    float GetThemeWeight(long themeID) const;
};

float CEnvironmentThemePriorityStackEntry::GetThemeWeight(long themeID) const
{
    if (themeID < 0)
        return BaseWeight;
    for (unsigned long i = 0; i < Themes.Size(); ++i)
        if (Themes[i].ThemeID == themeID)
