    T* m_pBegin; T* m_pEnd; T* m_pCapacity;
    unsigned long size() const { return m_pEnd - m_pBegin; }
    T& operator[](unsigned long i) { return m_pBegin[i]; }
    void push_back(const T& value) { *m_pEnd++ = value; }
